def mulx(x, n, stem):
    X, N = D(x), D(n); key = "$%s$" % num(X * N)
    c = [("$%s$" % num(X * N * 10), r"Ученик неверно поставил запятую в произведении: после запятой должно быть столько знаков, сколько их в обоих множителях вместе."),
         ("$%s$" % num(X * N / 10), r"Ученик отделил запятой лишний знак в произведении."),
         ("$%s$" % num(X + N), r"Ученик сложил числа вместо умножения.")]
    return P(stem % (src(x), src(n)), key, uniq(key, c))
