    c = [(r"$%s$ тыс." % num(X / 100), r"Ученик разделил на $100$ вместо $1000$."), (r"$%s$ тыс." % num(X / 10000), r"Ученик разделил на $10\,000$ вместо $1000$."), (r"$%s$ тыс." % num(X), r"Ученик не разделил число на $1000$.")]
    return P(TH % num(X), key, uniq(key, c))
